import {fromExif,isOtherBrand,drawFrame,uniqueName,BAR_RATIO,DEFAULT_CAPTION} from './core.js?v=6';
import {readLens} from './lens.js?v=6';
const $=id=>document.getElementById(id),form=$('metadata'),items=[];let selected=null,busy=false,cancelled=false,previewToken=0,defaultCaption=DEFAULT_CAPTION;const fields=['model','lens','date','focal','aperture','iso','shutter','caption'];
const bar=new Image();bar.src='assets/nikon-bar_v1.jpg';const barReady=Promise.all([bar.decode(),document.fonts.load('400 62px "Frame Model"'),document.fonts.load('400 62px "Frame Parameters"')]);barReady.catch(()=>setStatus('信息栏资源加载失败，请刷新页面'));
function setStatus(message){$('status').textContent=message;}
function setErrors(messages){$('errors').hidden=!messages.length;$('errors').textContent=messages.join('\n');}
function controls(){for(const id of ['add','empty-add','clear'])$(id).disabled=busy||(id==='clear'&&!items.length);$('export-one').disabled=busy||!selected||(selected.otherBrand&&!selected.confirmed);$('export-all').disabled=busy||!items.length;for(const el of form.elements)el.disabled=busy||!selected;$('brand-confirm').disabled=busy;$('total').textContent=items.length;}
function renderList(){const list=$('list');list.replaceChildren();if(!items.length){const p=document.createElement('p');p.className='list-empty';p.textContent='导入后在这里切换照片';list.append(p);}for(const item of items){const b=document.createElement('button');b.className='photo-item'+(item===selected?' selected':'');b.setAttribute('aria-pressed',String(item===selected));b.disabled=busy;b.title=item.file.name;const img=document.createElement('img');img.src=item.thumb;img.alt='';const details=document.createElement('span'),name=document.createElement('span'),size=document.createElement('small');name.className='filename';name.textContent=item.file.name;size.textContent=`${item.width} × ${item.height}`;details.append(name,size);b.append(img,details);b.addEventListener('click',()=>select(item));list.append(b);}controls();}
function syncForm(){for(const key of fields)form.elements[key].value=selected?.info[key]??'';$('focal-label').textContent=`焦距 / mm${selected?.info.focalSource?' · '+selected.info.focalSource:''}`;$('exif-state').textContent=selected?(selected.info.lens?'EXIF 已读取':selected.hasExif?'镜头未找到':'信息待补充'):'等待导入';$('brand-warning').hidden=!selected?.otherBrand;$('brand-confirm').checked=selected?.confirmed??false;controls();}
async function decode(file){try{return await createImageBitmap(file,{imageOrientation:'from-image',colorSpaceConversion:'default'});}catch{const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();return img;}finally{URL.revokeObjectURL(url);}}}
function release(img){img?.close?.();}
async function preview(){const token=++previewToken,item=selected;if(!item){$('empty').hidden=false;$('preview-wrap').hidden=true;$('preview').width=1;$('preview').height=1;return;}try{const image=await decode(item.file);try{await barReady;if(token!==previewToken)return;const result=drawFrame($('preview'),image,item.info,bar,Math.min(1600,image.width));$('empty').hidden=true;$('preview-wrap').hidden=false;$('dimensions').textContent=`${item.width} × ${item.height+Math.round(item.width*BAR_RATIO)} px`;}finally{release(image);}}catch{if(token===previewToken)setErrors([`${item.file.name}：预览失败，浏览器可能无法处理该尺寸`]);}}
function select(item){if(busy)return;selected=item;syncForm();renderList();preview();setStatus(item.file.name);}
async function importFiles(files){if(busy)return;busy=true;controls();setErrors([]);const failures=[];let added=0;try{for(const [index,file]of Array.from(files).entries()){setStatus(`正在读取 ${index+1} / ${files.length}`);if(!/\.(jpe?g|png|webp)$/i.test(file.name)){failures.push(`${file.name}：请选择 JPG、PNG 或 WebP`);continue;}let image;try{image=await decode(file);if(!image.width||!image.height)throw new Error('图片无效');let tags={};try{tags=await exifr.parse(file,{tiff:true,exif:true,xmp:true,gps:false,translateValues:true,reviveValues:true});}catch{}tags=tags??{};const exifInfo=fromExif(tags);exifInfo.lens=await readLens(file,tags);const info={...exifInfo,caption:defaultCaption},thumbCanvas=document.createElement('canvas');const scale=Math.min(1,160/image.width,160/image.height);thumbCanvas.width=Math.round(image.width*scale);thumbCanvas.height=Math.round(image.height*scale);thumbCanvas.getContext('2d').drawImage(image,0,0,thumbCanvas.width,thumbCanvas.height);const thumb=thumbCanvas.toDataURL('image/jpeg',0.7);const item={id:crypto.randomUUID(),file,width:image.width,height:image.height,thumb,info,original:{...exifInfo},hasExif:Object.values(exifInfo).some(Boolean),otherBrand:isOtherBrand(tags),confirmed:false};items.push(item);selected??=item;added++;}catch{failures.push(`${file.name}：读取失败，文件可能损坏或格式不受支持`);}finally{release(image);}}}finally{busy=false;syncForm();renderList();await preview();setStatus(`已导入 ${added} 张，共 ${items.length} 张`);setErrors(failures);$('files').value='';}}
$('add').onclick=$('empty-add').onclick=()=>$('files').click();$('files').onchange=e=>importFiles(e.target.files);
let dragDepth=0;document.addEventListener('dragenter',e=>{if(e.dataTransfer?.types.includes('Files')){e.preventDefault();dragDepth++;$('drop-zone').classList.add('dragging');}});document.addEventListener('dragover',e=>e.preventDefault());document.addEventListener('dragleave',()=>{dragDepth=Math.max(0,dragDepth-1);if(!dragDepth)$('drop-zone').classList.remove('dragging');});document.addEventListener('drop',e=>{e.preventDefault();dragDepth=0;$('drop-zone').classList.remove('dragging');if(e.dataTransfer?.files.length)importFiles(e.dataTransfer.files);});
form.onsubmit=e=>e.preventDefault();form.addEventListener('input',e=>{if(!selected||busy||!fields.includes(e.target.name))return;selected.info[e.target.name]=e.target.value.trim();if(e.target.name==='focal')selected.info.focalSource='手动';clearTimeout(form.previewTimer);form.previewTimer=setTimeout(preview,180);});$('reset').onclick=()=>{if(selected&&!busy){selected.info={...selected.original,caption:selected.info.caption};syncForm();preview();}};$('brand-confirm').onchange=e=>{if(selected){selected.confirmed=e.target.checked;controls();}};
$('apply-caption').onclick=()=>{if(busy||!selected)return;defaultCaption=selected.info.caption;for(const item of items)item.info.caption=defaultCaption;preview();setStatus('句子已应用到全部照片');};
$('clear').onclick=()=>{if(busy)return;items.length=0;selected=null;syncForm();renderList();preview();setErrors([]);setStatus('照片已清空');};
function validate(item){if(item.otherBrand&&!item.confirmed)throw new Error('需先确认使用尼康信息栏');for(const [key,max]of [['focal',10000],['aperture',256],['iso',10000000]]){const value=item.info[key];if(value!==''&&(!Number.isFinite(Number(value))||Number(value)<=0||Number(value)>max||(key==='iso'&&!Number.isInteger(Number(value)))))throw new Error('请检查焦距、光圈或 ISO');}if(item.info.shutter&&!/^(\d+(?:\.\d+)?|1\/\d+(?:\.\d+)?)$/.test(item.info.shutter))throw new Error('快门请填写秒数或 1/250 形式');if(item.info.shutter&&item.info.shutter.split('/').some(n=>Number(n)<=0))throw new Error('快门必须大于 0');}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function exportBlob(item){validate(item);let image,canvas;try{image=await decode(item.file);await barReady;canvas=document.createElement('canvas');drawFrame(canvas,image,item.info,bar);return await new Promise((ok,no)=>canvas.toBlob(blob=>blob?ok(blob):no(new Error('尺寸超出浏览器支持范围，请使用较小照片')),'image/jpeg',.95));}finally{release(image);if(canvas){canvas.width=1;canvas.height=1;}}}
let terminateZip=null;$('cancel').onclick=()=>{cancelled=true;terminateZip?.();terminateZip=null;setStatus('正在取消…');};
function zipFiles(data){return new Promise((resolve,reject)=>{const cancel=fflate.zip(data,{level:0},(error,result)=>{terminateZip=null;error?reject(error):resolve(result);});terminateZip=()=>{cancel();reject(new Error('cancelled'));};});}
async function exportPhotos(batch){if(busy||!selected)return;busy=true;cancelled=false;clearTimeout(form.previewTimer);controls();renderList();setErrors([]);$('progress-wrap').hidden=false;$('progress').value=0;const failures=[],used=new Set(),queue=batch?[...items]:[selected],data={};let count=0;try{for(const [index,item]of queue.entries()){if(cancelled)break;setStatus(`正在导出 ${index+1} / ${queue.length}`);try{const blob=await exportBlob(item);if(cancelled)break;const name=uniqueName(item.file.name,used);if(batch)data[name]=new Uint8Array(await blob.arrayBuffer());else download(blob,name);count++;}catch(e){failures.push(`${item.file.name}：${e.message}`);}$('progress').value=(index+1)/queue.length*90;await new Promise(r=>setTimeout(r,0));}if(batch&&count&&!cancelled){setStatus('正在打包 ZIP…');const zip=await zipFiles(data);if(!cancelled)download(new Blob([zip],{type:'application/zip'}),'尼康边框照片.zip');}$('progress').value=100;setStatus(cancelled?'导出已取消':`已导出 ${count} 张${failures.length?'，失败 '+failures.length+' 张':''}`);}catch(e){if(!cancelled){failures.push('打包失败：浏览器内存不足时，请减少批量照片数量');setStatus('批量导出失败');}else setStatus('导出已取消');}finally{terminateZip=null;busy=false;$('progress-wrap').hidden=true;controls();renderList();setErrors(failures);}}
$('export-one').onclick=()=>exportPhotos(false);$('export-all').onclick=()=>exportPhotos(true);
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'read_photo_frame_state',description:'读取已导入照片的数量、当前拍摄信息和批量处理状态。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw new Error('无需参数');return {count:items.length,busy,current:selected?{name:selected.file.name,information:{...selected.info}}:null};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
controls();


